const book = $input.first().json;
const endpoint = typeof process !== 'undefined' && process.env && process.env.BOOK_TEXT_API_URL ? process.env.BOOK_TEXT_API_URL : 'http://host.docker.internal:8001/book-text';
const backoffSteps = [1, 3, 10, 30, 120];
const nextRetryCount = Number(book.quote_extract_retry_count || 0) + 1;
const nextRetryAt = new Date(Date.now() + backoffSteps[Math.min(nextRetryCount - 1, backoffSteps.length - 1)] * 60000).toISOString();
const truncate = (value, maxLength) => Array.from(String(value || '')).slice(0, maxLength).join('');
const shortError = value => truncate(value, 500);

const response = await fetch(endpoint, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ id: book.id, title: book.title, author: book.author })
}).catch(error => ({ ok: false, status: 0, json: async () => ({ error: { message: error.message } }) }));

const payload = typeof response.json === 'function' ? await response.json().catch(() => ({})) : {};
if (!response.ok) {
  return [{ json: { ...book, success: false, quote_extract_retry_count: nextRetryCount, quote_extract_next_retry_at: nextRetryAt, quote_extract_error_reason: shortError(payload?.error?.message || payload?.message || `book_text_${response.status}`) } }];
}

const candidates = [payload.text, payload.book_text, payload.content, payload.body, payload.data, typeof payload === 'string' ? payload : ''];
const bookText = candidates.find(value => typeof value === 'string' && value.trim().length > 0) || '';
if (bookText.trim().length < 200) {
  return [{ json: { ...book, success: false, quote_extract_retry_count: nextRetryCount, quote_extract_next_retry_at: nextRetryAt, quote_extract_error_reason: 'book_text_empty_or_short' } }];
}

const truncatedText = truncate(bookText, 12000);
const prompt = `다음 책 본문에서 실제로 등장하는 완전한 한국어 문장 3개를 고르세요.\n\n책: ${book.title} (${book.author})\n\n규칙:\n- 반드시 아래 본문에 있는 문장만 원문 그대로 복사하세요.\n- 한 문장은 15자 이상 400자 이하로 고르세요.\n- 설명, 번호, 코드블록 없이 JSON 배열만 반환하세요.\n- 본문에 없는 문장을 만들면 안 됩니다.\n\n본문:\n${truncatedText}\n\n출력 예시:\n["문장 1", "문장 2", "문장 3"]`;

return [{ json: { ...book, success: true, book_text: truncatedText, book_text_length: Array.from(bookText).length, prompt } }];

const book = $('책 본문 조회').first().json;
const response = $input.first().json;
const model = 'llama-3.3-70b-versatile';
const backoffSteps = [1, 3, 10, 30, 120];
const nextRetryCount = Number(book.quote_extract_retry_count || 0) + 1;
const nextRetryAt = new Date(Date.now() + backoffSteps[Math.min(nextRetryCount - 1, backoffSteps.length - 1)] * 60000).toISOString();
const normalize = value => String(value || '').normalize('NFKC').toLowerCase().replace(/[\u201C\u201D\u2018\u2019"']/g, '').replace(/\s+/g, ' ').trim();
const escape = value => String(value || '').replace(/'/g, "''");
const sourceText = normalize(book.book_text);

if (response.error) {
  return [{ json: { ...book, success: false, quote_extract_retry_count: nextRetryCount, quote_extract_next_retry_at: nextRetryAt, quote_extract_error_reason: response.error?.message || 'groq_error' } }];
}

const text = response?.choices?.[0]?.message?.content || '';
const cleaned = text.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
const start = cleaned.indexOf('[');
const end = cleaned.lastIndexOf(']');

if (start === -1 || end === -1 || end <= start) {
  return [{ json: { ...book, success: false, quote_extract_retry_count: nextRetryCount, quote_extract_next_retry_at: nextRetryAt, quote_extract_error_reason: 'parse_failed' } }];
}

let quotes;
try {
  quotes = JSON.parse(cleaned.slice(start, end + 1));
} catch (error) {
  return [{ json: { ...book, success: false, quote_extract_retry_count: nextRetryCount, quote_extract_next_retry_at: nextRetryAt, quote_extract_error_reason: 'json_parse:' + error.message } }];
}

if (!Array.isArray(quotes) || quotes.length === 0) {
  return [{ json: { ...book, success: false, quote_extract_retry_count: nextRetryCount, quote_extract_next_retry_at: nextRetryAt, quote_extract_error_reason: 'empty_quotes' } }];
}

const seen = new Set();
const validQuotes = quotes.filter(quote => {
  if (typeof quote !== 'string' || quote.trim().length === 0) return false;
  const normalizedQuote = normalize(quote);
  if (normalizedQuote.length < 15 || normalizedQuote.length > 400) return false;
  if (!sourceText.includes(normalizedQuote)) return false;
  if (seen.has(normalizedQuote)) return false;
  seen.add(normalizedQuote);
  return true;
}).slice(0, 3);

if (validQuotes.length === 0) {
  return [{ json: { ...book, success: false, quote_extract_retry_count: nextRetryCount, quote_extract_next_retry_at: nextRetryAt, quote_extract_error_reason: 'quotes_not_in_source_text' } }];
}

const valuesClause = validQuotes.map(quote => {
  const normalizedQuote = normalize(quote);
  return '(' + book.id + ', \'' + escape(quote) + '\', \'' + escape(normalizedQuote) + '\', md5(\'' + escape(normalizedQuote) + '\'), \'' + model + '\')';
}).join(',\n');

return [{ json: { ...book, success: true, values_clause: valuesClause, quote_count: validQuotes.length, source_model: model, quote_extracted_at: new Date().toISOString() } }];

