INSERT INTO quotes (book_id, quote_raw, normalized_quote, content_hash, source_model)
VALUES {{ $json.values_clause }}
ON CONFLICT (book_id, content_hash) DO NOTHING;

UPDATE books
SET quote_extract_retry_count = {{ $json.quote_extract_retry_count || 0 }},
    quote_extract_next_retry_at = '{{ $json.quote_extract_next_retry_at }}'::timestamp,
    quote_extract_error_reason = {{ $json.quote_extract_error_reason ? "'" + $json.quote_extract_error_reason.replace(/'/g, "''") + "'" : 'NULL' }}
WHERE id = {{ $json.id }};
